import { nodes, tasks, lossPlan, treeRoots } from './results-content.js?v=20261018-t1';
import { mountTree } from './results-tree.js?v=20261018-t1';

// Scores, progress and filmed clips of each training run, regenerated by scripts/sync_results_site.py. Loaded
// fresh on every visit so the page follows training without a cache-busting edit.
const gen = await import(`./results-runs.js?t=${Date.now()}`);
const { runs, updated } = gen;
const lineage = gen.lineage || {}, robust = gen.robust || { rows: [], pending: [] };

// Hypotheses from the queue (experiments/queue.json entries with "site") join the tree without a hand edit:
// replicates become another seed of their parent, tests a new node at the end of the parent's branch.
for (const [parentId, ids] of Object.entries(gen.replicates || {})) {
  const p = nodes.find(n => n.id === parentId);
  if (p) p.runs = [...(p.runs || []), ...ids.filter(id => !(p.runs || []).includes(id))];
}
for (const extra of gen.extraNodes || []) {
  const at = nodes.findIndex(n => n.id === extra.parent);
  if (at < 0 || nodes.some(n => n.id === extra.id)) continue;
  let end = at + 1;
  while (end < nodes.length && nodes[end].depth > nodes[at].depth) end++;
  nodes.splice(end, 0, { ...extra, depth: Math.min(1, nodes[at].depth + 1), clips: [], next: extra.next || '' });
}

const $ = id => document.getElementById(id);
const video = $('video'), tree = $('tree');
const TASK_ORDER = ['pick_place_any', 'bin', 'handover', 'two_bins'];
let current = null, clipIndex = 0;

function el(tag, cls, text) {
  const node = document.createElement(tag);
  if (cls) node.className = cls;
  if (text !== undefined) node.textContent = text;
  return node;
}

const fmt = n => n.toLocaleString('en-US');
const seedName = id => `Seed ${(id.match(/_s(\d+)$/) || [0, 0])[1]}`;
const delayName = d => `${(d / 50).toFixed(2)} s delay`;
const outcome = c => c.success ? `Done in ${c.seconds.toFixed(1)} s` : `Not finished in ${Math.round(c.seconds)} s`;
const clipName = c => (c.label ? `${c.label} · ` : '') + tasks[c.task].short;

// Everything a node shows that comes from its runs.
function live(node) {
  if (node.robust) return { list: [], state: robust.pending.length ? 'running' : 'finished', clips: [...node.clips], score: null };
  const list = (node.runs || []).map(id => ({ id, ...(runs[id] || { scores: [], clips: [], state: 'queued' }) }));
  const plain = list.flatMap(r => r.scores.filter(s => s.delay === 0 && !s.goal));
  const states = list.map(r => r.state);
  const running = states.some(s => s === 'running' || s === 'starting');
  const state = node.kind === 'dead' || node.kind === 'main' ? node.kind
    : running ? 'running' : list.length && states.every(s => s === 'queued') ? 'queued'
    : list.length && states.every(s => s === 'done' || s === 'stopped') ? 'finished' : node.kind;
  const clips = [...node.clips];
  for (const r of list) {
    for (const c of r.clips) {
      const score = r.scores.find(s => s.step === c.step && s.delay === 0 && s.goal === c.goal);
      clips.push({ ...c, rate: score ? score.tasks[TASK_ORDER.indexOf(c.task)] : undefined,
        label: `${list.length > 1 ? seedName(r.id) + ' · ' : ''}step ${fmt(c.step)}${c.goal ? ' · with goal picture' : ''}` });
    }
  }
  const score = !node.runs ? node.score
    : plain.length ? { value: Math.round(plain.reduce((a, s) => a + s.total, 0) / plain.length), of: 120,
        label: `average of ${plain.length} checkpoint${plain.length > 1 ? 's' : ''}` } : null;
  return { list, state, clips, score };
}

const views = new Map(nodes.map(n => [n.id, live(n)]));
const kindLabel = { running: 'running', queued: 'queued', finished: 'trained, being judged', dead: 'dropped', main: '' };
const stateLabel = (node, view) => node.robust ? (view.state === 'running' ? 'testing' : 'tested') : kindLabel[view.state];

const items = new Map();
for (const node of nodes) {
  const view = views.get(node.id);
  const li = el('li', 'node');
  li.dataset.kind = view.state;
  li.dataset.depth = String(node.depth);
  li.id = node.id;
  const head = el('button', 'node-head');
  head.type = 'button';
  head.setAttribute('aria-expanded', 'false');
  head.append(el('span', 'node-when', node.when + (stateLabel(node, view) ? ` · ${stateLabel(node, view)}` : '')),
    el('span', 'node-name', node.name));
  const score = el('span', 'node-score');
  if (view.score) {
    const bar = el('span', 'bar'), fill = el('i');
    fill.style.width = `${Math.max(2, 100 * view.score.value / view.score.of)}%`;
    bar.append(fill);
    const num = el('span', 'node-num');
    num.append(el('b', '', String(view.score.value)), ` / ${view.score.of}`);
    score.append(bar, num);
  }
  score.append(el('span', 'node-clips', view.clips.length ? `▶ ${view.clips.length}` : ''));  // fixed slot keeps the bars aligned
  head.append(score);
  head.addEventListener('click', () => select(node, 0, true));
  li.append(head);
  items.set(node.id, li);
  tree.append(li);
}

// Per-checkpoint totals for a node's runs: one row per run, plus rows for delays and goal pictures when measured.
function scoreTable(view) {
  const rows = [];
  for (const r of view.list) {
    const name = seedName(r.id);
    const groups = new Map();
    for (const s of r.scores) {
      const key = `${s.goal ? 'g' : 'p'}${s.delay}`;
      if (!groups.has(key)) {
        groups.set(key, { label: name + (s.goal ? ', with goal picture' : s.delay ? `, ${delayName(s.delay)}` : ''),
          cells: new Map(), order: (s.goal ? 100 : 0) + s.delay });
      }
      groups.get(key).cells.set(s.step, s.total);
    }
    rows.push(...[...groups.values()].sort((a, b) => a.order - b.order));
  }
  if (!rows.length) return null;
  const steps = [...new Set(rows.flatMap(r => [...r.cells.keys()]))].sort((a, b) => a - b);
  const wrap = el('div', 'run-table-wrap');
  const table = el('table', 'run-table');
  table.append(el('caption', '', 'Successes out of 120 at each checkpoint (training step)'));
  const head = el('tr');
  head.append(el('th', 'step-head'), ...steps.map(s => el('th', 'step-head', fmt(s))));
  table.append(head);
  for (const r of rows) {
    const tr = el('tr');
    const th = el('th', '', r.label);
    th.scope = 'row';
    tr.append(th, ...steps.map(s => el('td', '', r.cells.has(s) ? String(r.cells.get(s)) : '·')));
    table.append(tr);
  }
  wrap.append(table);
  return wrap;
}

// Lighting-and-colour test: each model's score on the plain look and with random colours and lighting.
function ownerName(run) {
  const n = nodes.find(x => (x.runs || []).includes(run) || ((lossPlan[x.id] || {}).lines || []).some(l => l[0] === run));
  const seed = (run.match(/_s(\d+)$/) || [])[1];
  return n ? `${n.short || n.name}${seed !== undefined && n.runs && n.runs.length > 1 ? `, seed ${seed}` : ''}` : run;
}
function robustTable() {
  const out = [];
  if (robust.rows.length) {
    const wrap = el('div', 'run-table-wrap');
    const table = el('table', 'run-table robust-table');
    table.append(el('caption', '', 'Successes out of 120, same 30 layouts per task'));
    const head = el('tr');
    head.append(el('th', 'step-head', ''), el('th', 'step-head', 'Plain look'), el('th', 'step-head', 'Random colours and lighting'));
    table.append(head);
    for (const r of robust.rows) {
      const tr = el('tr');
      const th = el('th', '', `${ownerName(r.run)}, step ${fmt(r.step)}`);
      th.scope = 'row';
      const cell = el('td', '', String(r.total));
      cell.title = TASK_ORDER.map((t, i) => `${tasks[t].short} ${r.tasks[i]}`).join(' · ');
      tr.append(th, el('td', '', r.plain === null || r.plain === undefined ? '·' : String(r.plain)), cell);
      table.append(tr);
    }
    wrap.append(table);
    out.push(wrap);
  }
  if (robust.pending.length) {
    out.push(el('p', 'score-note', `Still being scored: ${robust.pending.map(p => `${ownerName(p.run)}, step ${fmt(p.step)}`).join(' · ')}.`));
  }
  return out;
}

function detail(node) {
  const view = views.get(node.id);
  const box = el('div', 'node-detail');
  const para = (label, text) => { const p = el('p'); p.append(el('span', '', label), text); return p; };
  box.append(para('What changed', node.changed));
  if (node.result) box.append(para('Result', node.result));
  if (node.robust) box.append(...robustTable());
  const table = scoreTable(view);
  if (table) box.append(table);
  const pending = view.list.filter(r => r.state !== 'done' && r.state !== 'stopped');
  if (pending.length) {
    box.append(el('p', 'score-note', pending.map(r => `${view.list.length > 1 ? seedName(r.id) + ': ' : ''}${
      r.state === 'queued' ? 'waiting for a free GPU' : r.state === 'starting' ? 'starting'
        : `training, step ${fmt(r.step)} of ${fmt(r.of)}`}`).join(' · ')));
  }
  if (view.score?.label) box.append(el('p', 'score-note', `Bar: ${view.score.label}, ${view.score.value} of ${view.score.of}.`));
  if (node.next) box.append(para(node.kind === 'main' ? 'Next' : view.state === 'dead' ? 'Why we moved on' : 'Now', node.next));
  if (view.clips.length > 1) {
    const chips = el('div', 'chips');
    chips.setAttribute('role', 'group');
    chips.setAttribute('aria-label', 'Videos for this experiment');
    view.clips.forEach((c, i) => {
      const chip = el('button', 'chip');
      chip.type = 'button';
      chip.setAttribute('aria-pressed', String(i === clipIndex));
      chip.append(el('i', c.success ? '' : 'is-miss'), clipName(c));
      chip.addEventListener('click', () => select(node, i, true));
      chips.append(chip);
    });
    box.append(chips);
  }
  return box;
}

// ------------------------------------------------------------------ Video | Loss
// The stage shows either the node's clip or its training loss. The loss data loads only when first asked for.
const SERIES = ['#3b5bb5', '#b8860b'], REF = '#8b8b84', NS = 'http://www.w3.org/2000/svg';
let mode = 'video', lossData = null, lossLoading = null, metric = 'f';
const viewParts = (new URLSearchParams(location.search).get('view') || '').split(',');
try { if (localStorage.getItem('results-stage') === 'loss') mode = 'loss'; } catch {}
for (const v of viewParts) if (v === 'loss' || v === 'video') mode = v;  // shareable: ?view=loss, ?view=tree,loss

function svg(tag, attrs = {}) {
  const node = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  return node;
}
const kfmt = v => v >= 1000 ? `${+(v / 1000).toFixed(1)}k` : String(Math.round(v));
const vfmt = v => v >= 1 ? v.toFixed(2) : v >= 0.1 ? v.toFixed(3) : v.toFixed(4);
const tfmt = v => String(+v.toPrecision(3));  // axis ticks: 0.03, 0.025, 0.2

// Debiased exponential moving average (as TensorBoard draws it); about 8% of the run per time constant.
function smooth(ys) {
  const a = 2 / (Math.max(3, Math.round(ys.length / 12)) + 1);
  let m = 0;
  return ys.map((y, i) => (m = a * y + (1 - a) * m) / (1 - (1 - a) ** (i + 1)));
}

function lossLines(node) {
  const plan = lossPlan[node.id] || {};
  const pick = pairs => pairs.map(([run, label]) => ({ run, label, curve: lossData[run] })).filter(l => l.curve);
  const own = plan.lines || (node.runs || []).map(id => [id, node.runs.length > 1 ? seedName(id) : 'This run']);
  if (!lossPlan[node.id] && node.auto) {  // a queue-derived node is drawn against its parent's runs
    const par = nodes.find(n => n.id === node.parent);
    plan.ref = (par?.runs || []).map(id => [id, 'Control']);
  }
  return { plan, lines: pick(own), ref: pick(plan.ref || []) };
}

function ticks(lo, hi, n, log) {
  if (log) {
    const out = [];
    for (let e = Math.floor(Math.log10(lo)); e <= Math.ceil(Math.log10(hi)); e++) {
      for (const m of [1, 2, 5]) { const v = m * 10 ** e; if (v >= lo && v <= hi) out.push(v); }
    }
    return out.length > 6 ? out.filter((v, i) => i % 2 === 0) : out;
  }
  const raw = (hi - lo) / n, mag = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= raw);
  const out = [];
  for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-12; v += step) out.push(+v.toFixed(10));
  return out;
}

function drawChart(plot, series, metricName) {
  plot.textContent = '';
  const W = plot.clientWidth, H = plot.clientHeight;
  if (W < 50 || H < 50) return;
  const M = { l: 46, r: 12, t: 6, b: 24 };
  const pts = series.flatMap(sr => sr.ys.map((y, i) => [sr.xs[i], y]));
  const sm = series.flatMap(sr => sr.sm);
  const xMax = Math.max(...pts.map(p => p[0]));
  // y range from the smoothed lines with a little room; raw noise beyond it is clipped
  let lo = Math.min(...sm), hi = Math.max(...sm);
  const log = hi / lo > 4;
  if (log) { lo /= 1.25; hi *= 1.25; } else { const pad = (hi - lo) * 0.15 || hi * 0.1; lo = Math.max(0, lo - pad); hi += pad; }
  const X = x => M.l + (W - M.l - M.r) * x / xMax;
  const Y = y => { const c = Math.min(hi, Math.max(lo, y)); const f = log ? Math.log(c / lo) / Math.log(hi / lo) : (c - lo) / (hi - lo); return H - M.b - f * (H - M.t - M.b); };
  const root = svg('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img',
    'aria-label': `${metricName} over training steps. ` + series.map(sr => `${sr.label}: ${vfmt(sr.sm.at(-1))} at step ${fmt(sr.xs.at(-1))}`).join('; ') + '.' });
  for (const v of ticks(lo, hi, 4, log)) {
    root.append(svg('line', { x1: M.l, x2: W - M.r, y1: Y(v), y2: Y(v), stroke: '#ebebe6', 'stroke-width': 1 }));
    const t = svg('text', { x: M.l - 6, y: Y(v) + 3.5, 'text-anchor': 'end' }); t.textContent = tfmt(v); root.append(t);
  }
  for (const v of ticks(0, xMax, 5, false)) {
    const t = svg('text', { x: X(v), y: H - 6, 'text-anchor': 'middle' }); t.textContent = kfmt(v); root.append(t);
  }
  root.append(svg('line', { x1: M.l, x2: W - M.r, y1: H - M.b, y2: H - M.b, stroke: '#d8d8d4' }));
  const path = (xs, ys) => xs.map((x, i) => `${i ? 'L' : 'M'}${X(x).toFixed(1)},${Y(ys[i]).toFixed(1)}`).join('');
  for (const sr of series) {  // raw first (faint), then the smoothed line on top
    if (!sr.ref) root.append(svg('path', { d: path(sr.xs, sr.ys), fill: 'none', stroke: sr.color, 'stroke-width': 1, opacity: 0.22 }));
  }
  for (const sr of series) {
    root.append(svg('path', { d: path(sr.xs, sr.sm), fill: 'none', stroke: sr.color, 'stroke-width': sr.ref ? 1.5 : 2,
      'stroke-dasharray': sr.ref ? '4 3' : 'none', 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));
  }
  const cross = svg('line', { y1: M.t, y2: H - M.b, stroke: '#1a1a1a33', visibility: 'hidden' });
  const dots = series.map(sr => svg('circle', { r: 3.5, fill: sr.color, stroke: '#fbfbfa', 'stroke-width': 2, visibility: 'hidden' }));
  root.append(cross, ...dots);
  const hit = svg('rect', { x: M.l, y: M.t, width: W - M.l - M.r, height: H - M.t - M.b, fill: 'transparent' });
  root.append(hit);
  plot.append(root);
  const tip = el('div', 'loss-tip');
  tip.hidden = true;
  plot.append(tip);
  const near = (xs, x) => { let a = 0, b = xs.length - 1; while (b - a > 1) { const m = (a + b) >> 1; xs[m] < x ? a = m : b = m; } return x - xs[a] < xs[b] - x ? a : b; };
  const move = e => {
    const r = root.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width * W;
    const step = Math.max(0, Math.min(xMax, (x - M.l) / (W - M.l - M.r) * xMax));
    tip.textContent = '';
    tip.append(el('b', '', `Step ${fmt(Math.round(step))}`));
    series.forEach((sr, k) => {
      const i = near(sr.xs, step);
      dots[k].setAttribute('cx', X(sr.xs[i])); dots[k].setAttribute('cy', Y(sr.sm[i])); dots[k].setAttribute('visibility', 'visible');
      const row = el('div');
      const sw = el('i'); sw.style.background = sr.color;
      row.append(sw, `${sr.label} ${vfmt(sr.sm[i])}`);
      tip.append(row);
    });
    cross.setAttribute('x1', X(step)); cross.setAttribute('x2', X(step)); cross.setAttribute('visibility', 'visible');
    tip.hidden = false;
    const px = X(step) / W * r.width;
    tip.style.left = `${Math.min(r.width - tip.offsetWidth - 4, Math.max(0, px + 12))}px`;
    tip.style.top = '8px';
  };
  const leave = () => { tip.hidden = true; cross.setAttribute('visibility', 'hidden'); dots.forEach(d => d.setAttribute('visibility', 'hidden')); };
  hit.addEventListener('pointermove', move);
  hit.addEventListener('pointerdown', move);
  hit.addEventListener('pointerleave', leave);
}

function renderLoss(node) {
  const view = $('loss-view');
  view.textContent = '';
  const head = el('div', 'loss-head');
  head.append(el('span', 'loss-label', 'Training loss · lower means closer to the demonstrations'), el('span', 'loss-title', node.name));
  view.append(head);
  if (!lossData) { view.append(el('p', 'loss-empty', 'Loading the training curves…')); return; }
  const { plan, lines, ref } = lossLines(node);
  if (plan.note || !lines.length) {
    view.append(el('p', 'loss-empty', plan.note || 'No training log survives for this step.'));
    return;
  }
  const hasCE = lines.some(l => l.curve.c);
  if (!hasCE) metric = 'f';
  const series = [...lines.map((l, i) => ({ label: l.label, color: SERIES[i % SERIES.length], curve: l.curve })),
    ...(metric === 'f' ? ref.map((l, i) => ({ label: ref.length > 1 ? `Control, ${seedName(l.run).toLowerCase()}` : 'Control', color: REF, ref: true, curve: l.curve })) : [])]
    .map(sr => { const ys = sr.curve[metric] || sr.curve.f; return { ...sr, xs: sr.curve.s, ys, sm: smooth(ys) }; });
  if (series.length > 1) {
    const legend = el('div', 'loss-legend');
    const seen = new Set();
    for (const sr of series) {
      const name = sr.ref ? 'Matched control' : sr.label;
      if (seen.has(name)) continue;
      seen.add(name);
      const item = el('span');
      const sw = svg('svg', { viewBox: '0 0 18 6' });
      sw.append(svg('line', { x1: 0, x2: 18, y1: 3, y2: 3, stroke: sr.color, 'stroke-width': sr.ref ? 1.5 : 2, 'stroke-dasharray': sr.ref ? '4 3' : 'none' }));
      item.append(sw, name);
      legend.append(item);
    }
    head.append(legend);
  }
  if (hasCE) {
    const tabs = el('div', 'loss-metric');
    tabs.setAttribute('role', 'group');
    tabs.setAttribute('aria-label', 'Which loss');
    for (const [key, label] of [['f', 'Action loss'], ['c', 'Action-token loss']]) {
      const b = el('button', '', label);
      b.type = 'button';
      b.setAttribute('aria-pressed', String(metric === key));
      b.addEventListener('click', () => { metric = key; renderLoss(node); });
      tabs.append(b);
    }
    head.append(tabs);
  }
  const plot = el('div', 'loss-plot');
  view.append(plot);
  const longest = Math.max(...series.map(sr => sr.xs.at(-1)));
  view.append(el('p', 'loss-foot', `Steps count from the start of each run (${fmt(longest)} at most). Faint: the logged values; solid: smoothed.` +
    (metric === 'c' ? ' The action-token loss trains the language model to predict compressed actions as text.' : '')));
  const name = metric === 'c' ? 'Action-token loss' : 'Action loss';
  requestAnimationFrame(() => drawChart(plot, series, name));
  plot._redraw = () => drawChart(plot, series, name);
}

async function setMode(next, remember) {
  mode = next;
  if (remember) { try { localStorage.setItem('results-stage', mode); } catch {} }
  $('view-video').setAttribute('aria-pressed', String(mode === 'video'));
  $('view-loss').setAttribute('aria-pressed', String(mode === 'loss'));
  if (mode === 'loss' && !lossData) {
    lossLoading ||= import(`./results-loss.js?t=${Date.now()}`).then(m => { lossData = m.loss; }).catch(() => { lossData = {}; });
    show(current);
    await lossLoading;
  }
  show(current);
}
$('view-video').addEventListener('click', () => setMode('video', true));
$('view-loss').addEventListener('click', () => setMode('loss', true));
new ResizeObserver(() => { const plot = document.querySelector('.loss-plot'); if (plot?._redraw && mode === 'loss') plot._redraw(); }).observe($('loss-view'));

function show(node) {
  const stage = document.querySelector('.results-stage');
  stage.classList.toggle('show-loss', mode === 'loss');
  $('loss-view').hidden = mode !== 'loss';
  if (mode === 'loss') {
    video.pause();
    video.hidden = true;
    $('clip-card').hidden = true;
    $('stage-empty').hidden = true;
    renderLoss(node);
    return;
  }
  const c = views.get(node.id).clips[clipIndex];
  $('stage-empty').hidden = Boolean(c);
  $('clip-card').hidden = !c;
  video.hidden = !c;
  if (!c) {
    video.pause();
    video.removeAttribute('src');
    video.load();
    $('empty-title').textContent = node.name;
    return;
  }
  const task = tasks[c.task];
  $('clip-label').textContent = `${node.name}${c.label ? ' · ' + c.label : ''}`;
  $('clip-title').textContent = task.name;
  const line = $('clip-outcome');
  line.textContent = '';
  line.append(el('i', `outcome-mark${c.success ? '' : ' is-miss'}`), outcome(c),
    el('span', 'clip-goal', c.rate !== undefined ? ` · succeeds in ${c.rate} of ${c.of || 30} random layouts` : ` · layout ${c.layout} of 30`));
  video.poster = c.poster;
  video.src = c.video;
  video.setAttribute('aria-label', `${node.name}: ${task.name}. ${task.goal} ${outcome(c)}.`);
  video.play().catch(() => {});
}

function select(node, index, userChose) {
  current = node;
  clipIndex = Math.min(index, Math.max(0, views.get(node.id).clips.length - 1));
  for (const [id, li] of items) {
    const on = id === node.id;
    li.setAttribute('aria-current', String(on));
    li.querySelector('.node-head').setAttribute('aria-expanded', String(on));
    li.querySelector('.node-detail')?.remove();
    if (on) li.append(detail(node));
  }
  show(node);
  lineageTree?.highlight(node.id);
  if (layout === 'tree') { const d = $('lineage-detail'); d.textContent = ''; d.append(detail(node)); }
  $('counter').textContent = `${nodes.indexOf(node) + 1} of ${nodes.length}`;
  if (userChose) history.replaceState(null, '', `#${node.id}${clipIndex ? '/' + clipIndex : ''}`);
}

// ------------------------------------------------------------------ List | Tree
let layout = 'list', lineageTree = null;
try { if (localStorage.getItem('results-layout') === 'tree') layout = 'tree'; } catch {}
for (const v of viewParts) if (v === 'tree' || v === 'list') layout = v;
const describe = node => {
  const view = views.get(node.id);
  const label = stateLabel(node, view);
  const note = (node.changed.match(/^.*?[.!?](\s|$)/) || [node.changed])[0].trim();
  const pending = view.list.filter(r => r.state !== 'done' && r.state !== 'stopped');
  const progress = pending.map(r => r.state === 'queued' ? 'waiting for a free GPU' : r.state === 'starting' ? 'starting'
    : `training, step ${fmt(r.step)} of ${fmt(r.of)}`).join(' · ');
  const rob = robust.rows.filter(r => (node.runs || []).includes(r.run) || ((lossPlan[node.id] || {}).lines || []).some(l => l[0] === r.run));
  const score = view.score ? `${view.score.value} of ${view.score.of}${view.score.label ? ` (${view.score.label})` : ''}` +
    (rob.length ? ` · ${rob.map(r => r.total).join(', ')} with random colours and lighting` : '') : '';
  return { when: node.when + (label ? ` · ${label}` : ''), note, progress, score,
    label: `${node.name}${label ? `, ${label}` : ''}${score ? `, ${score}` : ''}` };
};
function setLayout(next, remember) {
  layout = next;
  if (remember) { try { localStorage.setItem('results-layout', layout); } catch {} }
  $('layout-list').setAttribute('aria-pressed', String(layout === 'list'));
  $('layout-tree').setAttribute('aria-pressed', String(layout === 'tree'));
  tree.hidden = layout === 'tree';
  $('lineage').hidden = layout !== 'tree';
  if (layout === 'tree') {
    lineageTree ||= mountTree({ nodes, views, lineage, lossPlan, roots: treeRoots, select, describe });
    lineageTree.fit();
    if (current) select(current, clipIndex, false);
  }
}
$('layout-list').addEventListener('click', () => setLayout('list', true));
$('layout-tree').addEventListener('click', () => setLayout('tree', true));

$('updated').textContent = `Updated ${updated}. Scores, progress and videos follow training as it runs.`;

// Start at the hash, else the best model so far (the latest kept experiment with a video).
const [hashId, hashClip] = location.hash.slice(1).split('/');
const start = nodes.find(n => n.id === hashId) || [...nodes].reverse().find(n => n.kind === 'main' && views.get(n.id).clips.length) || nodes[0];
select(start, Number(hashClip) || 0, false);
if (mode === 'loss') setMode('loss', false);
if (layout === 'tree') setLayout('tree', false);
else if (hashId) items.get(start.id).scrollIntoView({ block: 'center' });

addEventListener('keydown', e => {
  if (e.target === video || e.target.closest('input, textarea, [contenteditable], a, .stage-switch, .loss-metric, .layout-switch, .lineage') || e.metaKey || e.ctrlKey) return;
  const i = nodes.indexOf(current), n = views.get(current.id).clips.length;
  const go = (node, k) => { e.preventDefault(); select(node, k, true); if (layout === 'list') items.get(node.id).scrollIntoView({ block: 'nearest' }); };
  if (e.key === 'ArrowDown' && i < nodes.length - 1) go(nodes[i + 1], 0);
  if (e.key === 'ArrowUp' && i > 0) go(nodes[i - 1], 0);
  if (e.key === 'ArrowRight' && clipIndex < n - 1) go(current, clipIndex + 1);
  if (e.key === 'ArrowLeft' && clipIndex > 0) go(current, clipIndex - 1);
});
